// engine.js - the debugger engine in JavaScript: processor emulation and the disassembler.
//
// The emulation is a line-by-line port of cpu16.cpp (specification, revision 6): the same order of
// micro-steps, the same flags, ERRCMD for reserved and constrained-unpredictable
// encodings, the same console port $FF20. The match is checked by test_engine.js,
// which compares the state with C++ on random programs.
//
// The ISA tables (names, classes, validity) come from the ISA object generated by
// gen_isa_js.cpp from cpu16_isa.hpp.
//
// Devices: the console-display-keyboard-timer ($FF20..$FF29) is the class Cpu16Device, a port of
// ConsoleDevice; the real-time clock ($FF2A..$FF2E) is the class Cpu16Rtc, a port of RtcDevice;
// the disk controller ($FF30..$FF3B) is the class Cpu16Disk, a port of DiskController
// (all from cpu16_machine.hpp). The memory manager ($FF40..$FF48, 2 MB of physical memory) is in the
// engine itself, as in Cpu in cpu16.cpp. The window $FF20..$FFFF is not translated: an address without a device
// reads as 0, a write to it is ignored.
// It implements the engine contract described in debugger.template.html.

// The "console-display-keyboard-timer" device is a line-by-line port of ConsoleDevice from
// cpu16_machine.hpp (the document "CPU16 Machine: Memory and Devices"). The tables are from MACHINE.
class Cpu16Device {
  constructor() {
    this.chars = new Uint8Array(MACHINE.COLS * MACHINE.ROWS);
    this.attrs = new Uint8Array(MACHINE.COLS * MACHINE.ROWS);
    this.keys = [];                  // keyboard events { ch, scan, mods }
    this.ttyOut = [];                // bytes printed in teletype mode
    this.timerOn = false;
    this.clockFrozen = false;
    this.nextTick = 0;
    this.clock = () => Math.floor(performance.now() * 1000);   // microseconds
    this.screenVersion = 0;
    this.reset();
  }
  reset() {
    this.chars.fill(0x20); this.attrs.fill(MACHINE.ATTR_DEFAULT);
    this.col = 0; this.row = 0;
    this.ctrl = MACHINE.CTRL_DEFAULT; this.attr = MACHINE.ATTR_DEFAULT;
    this.keys = []; this.ttyOut = []; this.mods = 0;
    this.usedDisplay = false; this.timerOn = false;
    this.screenVersion++;
  }
  static isPort(a) { return a >= MACHINE.PORT_DATA && a <= MACHINE.PORT_TIMER; }
  pushKey(ch, scan, mods = 0) {
    if (this.keys.length < MACHINE.KEY_QUEUE_MAX) this.keys.push({ ch: ch & 0xFF, scan: scan & 0xFF, mods: mods & MACHINE.MOD_MASK });
  }
  // An event is taken whole; MODS are its modifiers (an empty queue: event 0, MODS = 0).
  pop() {
    const e = this.keys.length ? this.keys.shift() : { ch: 0, scan: 0, mods: 0 };
    this.mods = e.mods;
    return e;
  }

  read8(a) {
    const M = MACHINE;
    switch (a) {
      case M.PORT_DATA: return this.pop().ch;
      case M.PORT_SCAN: return this.pop().scan;
      case M.PORT_CTRL: return this.ctrl;
      case M.PORT_ATTR: return this.attr;
      case M.PORT_COL: return this.col;
      case M.PORT_ROW: return this.row;
      case M.PORT_COLS: return M.COLS;
      case M.PORT_ROWS: return M.ROWS;
      case M.PORT_TIMER: return this.timerOn ? 1 : 0;
      default: return 0;
    }
  }
  // A word at $FF20 is one access: the character and scancode of one event.
  read16(a) {
    if (a === MACHINE.PORT_DATA) { const e = this.pop(); return e.ch | (e.scan << 8); }
    return this.read8(a) | (this.read8((a + 1) & 0xFFFF) << 8);
  }
  write8(a, v) {
    const M = MACHINE;
    v &= 0xFF;
    switch (a) {
      case M.PORT_DATA: this.output(v); break;
      case M.PORT_CTRL: this.ctrl = v & M.CTRL_MASK; if (this.ctrl !== M.CTRL_DEFAULT) this.usedDisplay = true; this.screenVersion++; break;
      case M.PORT_ATTR: this.attr = v; this.usedDisplay = true; break;
      case M.PORT_COL: this.col = v < M.COLS ? v : M.COLS - 1; this.usedDisplay = true; this.screenVersion++; break;
      case M.PORT_ROW: this.row = v < M.ROWS ? v : M.ROWS - 1; this.usedDisplay = true; this.screenVersion++; break;
      case M.PORT_CMD: this.command(v); break;
      case M.PORT_TIMER: {
        const on = !!(v & 1);
        if (on && !this.timerOn) this.nextTick = this.clock() + M.TIMER_PERIOD_US;
        this.timerOn = on;
        break;
      }
      default: break;
    }
  }
  // Whether it is time to raise IRQ0. Ticks do not accumulate: a lagging timer catches up to "now".
  pollTimer() {
    if (!this.timerOn || this.clockFrozen) return false;
    const now = this.clock();
    if (now < this.nextTick) return false;
    this.nextTick += MACHINE.TIMER_PERIOD_US;
    if (this.nextTick <= now) this.nextTick = now + MACHINE.TIMER_PERIOD_US;
    return true;
  }
  resumeClock() { this.clockFrozen = false; this.nextTick = this.clock() + MACHINE.TIMER_PERIOD_US; }

  put(ch, at) { const i = this.row * MACHINE.COLS + this.col; this.chars[i] = ch; this.attrs[i] = at; }
  clearRange(from, to) { this.chars.fill(0x20, from, to); this.attrs.fill(this.attr, from, to); }
  scrollUp() {
    const C = MACHINE.COLS, N = C * MACHINE.ROWS;
    this.chars.copyWithin(0, C, N); this.attrs.copyWithin(0, C, N);
    this.clearRange(N - C, N);
  }
  scrollDown() {
    const C = MACHINE.COLS, N = C * MACHINE.ROWS;
    this.chars.copyWithin(C, 0, N - C); this.attrs.copyWithin(C, 0, N - C);
    this.clearRange(0, C);
  }
  newlineTty() { if (++this.row === MACHINE.ROWS) { this.scrollUp(); this.row = MACHINE.ROWS - 1; } }
  // SCRD (the machine, sect. 2.2, revision 9): the cell at the position; advance - move the position (a word read)
  readCell(advance) {
    const i = this.row * MACHINE.COLS + this.col;
    const v = this.chars[i] | (this.attrs[i] << 8);
    if (advance) this.advanceRaw();
    return v;
  }
  advanceRaw() { if (++this.col === MACHINE.COLS) { this.col = 0; if (++this.row === MACHINE.ROWS) this.row = 0; } }
  output(v) {
    const M = MACHINE;
    this.screenVersion++;
    if (this.ctrl & M.CTRL_ATTRMODE) { this.attrs[this.row * M.COLS + this.col] = v; this.advanceRaw(); this.usedDisplay = true; return; }
    if (!(this.ctrl & M.CTRL_TTY)) { this.put(v, this.attr); this.advanceRaw(); this.usedDisplay = true; return; }
    if (v === 0) return;
    this.ttyOut.push(v);
    switch (v) {
      case 0x0A: this.col = 0; this.newlineTty(); break;
      case 0x0D: this.col = 0; break;
      case 0x08: if (this.col) this.col--; break;
      case 0x09:
        this.col = (Math.floor(this.col / 8) + 1) * 8;
        if (this.col >= M.COLS) { this.col = 0; this.newlineTty(); }
        break;
      default:
        this.put(v, this.attr);
        if (++this.col === M.COLS) { this.col = 0; this.newlineTty(); }
    }
  }
  command(v) {
    const M = MACHINE, pos = this.row * M.COLS + this.col;
    switch (v) {
      case M.CMD_CLS: this.clearRange(0, M.COLS * M.ROWS); this.col = 0; this.row = 0; break;
      case M.CMD_CLEOL: this.clearRange(pos, (this.row + 1) * M.COLS); break;
      case M.CMD_CLEOS: this.clearRange(pos, M.COLS * M.ROWS); break;
      case M.CMD_SCROLL_UP: this.scrollUp(); break;
      case M.CMD_SCROLL_DOWN: this.scrollDown(); break;
      default: return;
    }
    this.usedDisplay = true;
    this.screenVersion++;
  }
}

// A disk label from a file name: without the directory, up to 15 characters, foreign characters become '?' (diskLabelFromName).
function cpu16DiskLabel(name) {
  const base = name.replace(/^.*[\/\\]/, "");
  const out = [];
  for (const ch of base) {
    if (out.length >= MACHINE.DISK_LABEL_MAX) break;
    const code = Cpu16Engine.charsetCode(ch.codePointAt(0));
    out.push(code < 0x20 || code === 0x7F ? 0x3F : code);
  }
  return Uint8Array.from(out);
}

// The real-time clock is a line-by-line port of RtcDevice and the rtc* functions from cpu16_machine.hpp.
// Inside - seconds from 1 January 2025 AM 0:00:00 (base) at the moment anchor (microseconds of clock()).
// The clock runs while the debugger is paused too: it is time, not ticks.
class Cpu16Rtc {
  constructor() {
    this.base = 0;
    this.anchor = 0;
    this.clock = () => Math.floor(performance.now() * 1000);
    this.reset();
  }
  reset() { this.time = 0; this.date = 0; this.err = false; }
  static isPort(a) { return a >= MACHINE.RTC_FIRST && a <= MACHINE.RTC_LAST; }

  static leap(y) { return y % 4 === 3; }
  static daysInMonth(y, m) { return m === 2 && Cpu16Rtc.leap(y) ? 29 : [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]; }
  static validTime(t) { return (t >> 12) <= 11 && ((t >> 6) & 63) <= 59 && (t & 63) <= 59; }
  static validDate(d) {
    const y = d >> 10, m = (d >> 6) & 15, day = (d >> 1) & 31;
    return m >= 1 && m <= 12 && day >= 1 && day <= Cpu16Rtc.daysInMonth(y, m);
  }
  static valid(t, d) { return Cpu16Rtc.validTime(t) && Cpu16Rtc.validDate(d); }
  static dayNumber(y, m, day) {
    let n = y * 365 + Math.floor(y / 4);
    for (let k = 1; k < m; k++) n += Cpu16Rtc.daysInMonth(y, k);
    return n + day - 1;
  }
  static toSeconds(t, d) {
    const h24 = (t >> 12) + 12 * (d & 1);
    return Cpu16Rtc.dayNumber(d >> 10, (d >> 6) & 15, (d >> 1) & 31) * MACHINE.RTC_DAY + h24 * 3600 + ((t >> 6) & 63) * 60 + (t & 63);
  }
  // seconds -> { time, date }
  static fromSeconds(s) {
    let days = Math.floor(s / MACHINE.RTC_DAY);
    const tod = s % MACHINE.RTC_DAY;
    let y = 0, m = 1;
    while (days >= (Cpu16Rtc.leap(y) ? 366 : 365)) { days -= Cpu16Rtc.leap(y) ? 366 : 365; y++; }
    while (days >= Cpu16Rtc.daysInMonth(y, m)) { days -= Cpu16Rtc.daysInMonth(y, m); m++; }
    const h24 = Math.floor(tod / 3600);
    return { time: ((h24 % 12) << 12 | (Math.floor(tod / 60) % 60) << 6 | tod % 60) & 0xFFFF,
             date: (y << 10 | m << 6 | (days + 1) << 1 | (h24 >= 12 ? 1 : 0)) & 0xFFFF };
  }
  // seconds -> ordinary notation (the full year, hour 0..23)
  static civil(s) {
    const { time: t, date: d } = Cpu16Rtc.fromSeconds(s);
    return { year: MACHINE.RTC_BASE_YEAR + (d >> 10), month: (d >> 6) & 15, day: (d >> 1) & 31,
             hour: (t >> 12) + 12 * (d & 1), minute: (t >> 6) & 63, second: t & 63 };
  }
  // ordinary notation -> seconds; null - invalid or outside 2025..2088
  static fromCivil(c) {
    const ints = [c.year, c.month, c.day, c.hour, c.minute, c.second];
    if (!ints.every((v) => Number.isInteger(v) && v >= 0)) return null;
    if (c.year < MACHINE.RTC_BASE_YEAR || c.year >= MACHINE.RTC_BASE_YEAR + MACHINE.RTC_YEARS || c.month < 1 || c.month > 12) return null;
    const y = c.year - MACHINE.RTC_BASE_YEAR;
    if (c.day < 1 || c.day > Cpu16Rtc.daysInMonth(y, c.month) || c.hour > 23 || c.minute > 59 || c.second > 59) return null;
    return Cpu16Rtc.dayNumber(y, c.month, c.day) * MACHINE.RTC_DAY + c.hour * 3600 + c.minute * 60 + c.second;
  }
  // "DD.MM.YYYY HH:MM:SS" (24-hour notation) -> seconds; null - wrong format or invalid
  static parse(text) {
    const m = /^\s*(\d{2})\.(\d{2})\.(\d{4})\s+(\d{2}):(\d{2}):(\d{2})\s*$/.exec(text);
    if (!m) return null;
    const v = m.slice(1).map(Number);
    return Cpu16Rtc.fromCivil({ year: v[2], month: v[1], day: v[0], hour: v[3], minute: v[4], second: v[5] });
  }
  static format(s) {
    const c = Cpu16Rtc.civil(s), p = (n) => String(n).padStart(2, "0");
    return `${p(c.day)}.${p(c.month)}.${c.year} ${p(c.hour)}:${p(c.minute)}:${p(c.second)}`;
  }

  valueAt(now) {
    const P = MACHINE.RTC_PERIOD;
    const sec = Math.floor((now - this.anchor) / MACHINE.RTC_SECOND_US);
    return (((this.base + sec) % P) + P) % P;
  }
  value() { return this.valueAt(this.clock()); }
  set(s, anchorUs) { this.base = s % MACHINE.RTC_PERIOD; this.anchor = anchorUs; }
  setNow(s) { this.set(s, this.clock()); }
  // The host's local time (sect. 9.1): outside 2025..2088 - 1 January 2025 0:00:00; the machine's seconds
  // change together with the host's seconds.
  setHostTime(date = new Date()) {
    const s = Cpu16Rtc.fromCivil({ year: date.getFullYear(), month: date.getMonth() + 1, day: date.getDate(),
                                   hour: date.getHours(), minute: date.getMinutes(), second: date.getSeconds() });
    this.set(s === null ? 0 : s, this.clock() - (s === null ? 0 : date.getMilliseconds() * 1000));
  }

  read8(a) {
    const M = MACHINE;
    switch (a) {
      case M.RTC_TIME: return this.time & 0xFF;
      case M.RTC_TIME + 1: return this.time >> 8;
      case M.RTC_DATE: return this.date & 0xFF;
      case M.RTC_DATE + 1: return this.date >> 8;
      case M.RTC_STATUS: return this.err ? M.RTC_ERR : 0;
      default: return 0;
    }
  }
  write8(a, v) {
    const M = MACHINE;
    switch (a) {
      case M.RTC_TIME: this.time = (this.time & 0xFF00) | v; break;
      case M.RTC_TIME + 1: this.time = (this.time & 0x00FF) | (v << 8); break;
      case M.RTC_DATE: this.date = (this.date & 0xFF00) | v; break;
      case M.RTC_DATE + 1: this.date = (this.date & 0x00FF) | (v << 8); break;
      case M.RTC_CMD: this.command(v); break;
      default: break;
    }
  }
  command(c) {
    const M = MACHINE, R = Cpu16Rtc;
    const now = this.clock();
    const v = this.valueAt(now);
    switch (c) {
      case M.RTCC_READ: { const r = R.fromSeconds(v); this.time = r.time; this.date = r.date; break; }
      case M.RTCC_WRITE:
        this.err = !R.valid(this.time, this.date);
        if (!this.err) this.set(R.toSeconds(this.time, this.date), now);
        break;
      case M.RTCC_WRITE_TIME:
        this.err = !R.validTime(this.time);
        if (!this.err) this.set(R.toSeconds(this.time, (R.fromSeconds(v).date & ~1) | (this.date & 1)), now);
        break;
      case M.RTCC_WRITE_DATE:
        this.err = !R.validDate(this.date);
        if (!this.err) {
          const d = this.date;
          const nv = R.dayNumber(d >> 10, (d >> 6) & 15, (d >> 1) & 31) * M.RTC_DAY + v % M.RTC_DAY;
          this.base = (((this.base + nv - v) % M.RTC_PERIOD) + M.RTC_PERIOD) % M.RTC_PERIOD;
        }
        break;
      default: break;
    }
  }
}

// The disk controller is a line-by-line port of DiskController from cpu16_machine.hpp.
// A disk: { data: Uint8Array (512-byte sectors), readOnly, removable, label: Uint8Array, name }.
class Cpu16Disk {
  constructor() {
    this.disks = new Array(MACHINE.DISK_COUNT).fill(null);
    this.sectorDelayUs = 0;
    this.clockFrozen = false;
    this.nextAt = 0;
    this.clock = () => Math.floor(performance.now() * 1000);
    this.dmaRead = () => 0;
    this.dmaWrite = () => {};
    this.reset();
  }
  reset() { this.error = 0; this.disk = 0; this.count = 0; this.ctrl = 0; this.addr = 0; this.lba = 0; this.busy = false; this.done = false; this.cmd = 0; }
  static isPort(a) { return a >= MACHINE.DK_FIRST && a <= MACHINE.DK_LAST; }
  static sectors(d) { return Math.floor(d.data.length / MACHINE.SECTOR_SIZE); }
  drives() { let m = 0; this.disks.forEach((d, n) => { if (d) m |= 1 << n; }); return m; }
  status() {
    const M = MACHINE, d = this.disks[this.disk & 7];
    return (this.busy ? M.DKS_BUSY : 0) | (this.error ? M.DKS_ERR : 0) | (this.done ? M.DKS_DONE : 0) |
           (d ? M.DKS_PRESENT : 0) | (d && d.readOnly ? M.DKS_RO : 0);
  }
  irq() { return this.done && !!(this.ctrl & MACHINE.DK_IEN); }
  willIrq() { return this.busy && !!(this.ctrl & MACHINE.DK_IEN); }
  read8(a) {
    const M = MACHINE;
    switch (a) {
      case M.DK_STATUS: return this.status();
      case M.DK_ERROR: return this.error;
      case M.DK_DISK: return this.disk;
      case M.DK_COUNT: return this.count;
      case M.DK_ADDR: return this.addr & 0xFF;
      case M.DK_ADDR + 1: return this.addr >> 8;
      case M.DK_LBA_LO: return this.lba & 0xFF;
      case M.DK_LBA_LO + 1: return (this.lba >>> 8) & 0xFF;
      case M.DK_LBA_HI: return (this.lba >>> 16) & 0xFF;
      case M.DK_LBA_HI + 1: return this.lba >>> 24;
      case M.DK_CTRL: return this.ctrl;
      case M.DK_DRIVES: return this.drives();
      default: return 0;
    }
  }
  write8(a, v) {
    const M = MACHINE;
    v &= 0xFF;
    if (a === M.DK_CTRL) { this.ctrl = v & M.DK_IEN; return; }
    if (this.busy) return;
    switch (a) {
      case M.DK_CMD: this.start(v); break;
      case M.DK_DISK: this.disk = v & 7; break;
      case M.DK_COUNT: this.count = v; break;
      case M.DK_ADDR: this.addr = (this.addr & 0xFF00) | v; break;
      case M.DK_ADDR + 1: this.addr = (this.addr & 0x00FF) | (v << 8); break;
      case M.DK_LBA_LO: this.lba = ((this.lba & 0xFFFFFF00) | v) >>> 0; break;
      case M.DK_LBA_LO + 1: this.lba = ((this.lba & 0xFFFF00FF) | (v << 8)) >>> 0; break;
      case M.DK_LBA_HI: this.lba = ((this.lba & 0xFF00FFFF) | (v << 16)) >>> 0; break;
      case M.DK_LBA_HI + 1: this.lba = ((this.lba & 0x00FFFFFF) | (v << 24)) >>> 0; break;
      default: break;
    }
  }
  attach(n, d) { this.disks[n & 7] = d; }
  detach(n) {
    this.disks[n & 7] = null;
    if (this.busy && this.disk === (n & 7)) this.finish(MACHINE.DKE_IO);
  }
  poll() {
    if (!this.busy || this.clockFrozen) return;
    if (this.sectorDelayUs <= 0) { while (this.unit()) {} return; }
    const now = this.clock();
    while (this.busy && now >= this.nextAt) if (this.unit()) this.nextAt += this.sectorDelayUs;
  }
  resumeClock() { this.clockFrozen = false; this.nextAt = this.clock() + this.sectorDelayUs; }
  finish(err) { this.busy = false; this.done = true; this.error = err; }
  start(c) {
    const M = MACHINE;
    if (c === M.DKC_ACK) { this.done = false; return; }
    this.busy = true; this.done = false; this.error = M.DKE_OK; this.cmd = c;
    if (c > M.DKC_FLUSH) { this.finish(M.DKE_BADCMD); return; }
    const d = this.disks[this.disk];
    if (!d) { this.finish(M.DKE_NODISK); return; }
    if (c === M.DKC_READ || c === M.DKC_WRITE) {
      if (this.count === 0) { this.finish(M.DKE_OK); return; }
      if (c === M.DKC_WRITE && d.readOnly) { this.finish(M.DKE_READONLY); return; }
      if (this.lba + this.count > Cpu16Disk.sectors(d)) { this.finish(M.DKE_RANGE); return; }
      if (this.addr + M.SECTOR_SIZE * this.count - 1 > M.DMA_LIMIT) { this.finish(M.DKE_BADADDR); return; }
    } else if (c === M.DKC_INFO) {
      if (this.addr + M.DISK_INFO_SIZE - 1 > M.DMA_LIMIT) { this.finish(M.DKE_BADADDR); return; }
    }
    if (this.sectorDelayUs <= 0) { while (this.unit()) {} return; }
    this.nextAt = this.clock() + this.sectorDelayUs;
  }
  unit() {
    const M = MACHINE, S = M.SECTOR_SIZE;
    if (!this.busy) return false;
    const d = this.disks[this.disk];
    if (!d) { this.finish(M.DKE_IO); return false; }
    switch (this.cmd) {
      case M.DKC_READ: {
        if (this.lba >= Cpu16Disk.sectors(d)) { this.finish(M.DKE_IO); return false; }
        const off = this.lba * S;
        for (let i = 0; i < S; i++) this.dmaWrite((this.addr + i) & 0xFFFF, d.data[off + i]);
        break;
      }
      case M.DKC_WRITE: {
        if (this.lba >= Cpu16Disk.sectors(d)) { this.finish(M.DKE_IO); return false; }
        const off = this.lba * S;
        for (let i = 0; i < S; i++) d.data[off + i] = this.dmaRead((this.addr + i) & 0xFFFF);
        d.modified = true;
        break;
      }
      case M.DKC_INFO: {
        const info = new Uint8Array(M.DISK_INFO_SIZE), n = Cpu16Disk.sectors(d);
        for (let k = 0; k < 4; k++) info[k] = (n >>> (8 * k)) & 0xFF;
        info[4] = (d.readOnly ? M.DKI_RO : 0) | (d.removable ? M.DKI_REMOVABLE : 0) | (n <= 0x10000 ? M.DKI_SMALL : 0);
        const l = d.label || [];
        for (let k = 0; k < l.length && k < M.DISK_LABEL_MAX; k++) info[16 + k] = l[k];
        for (let i = 0; i < M.DISK_INFO_SIZE; i++) this.dmaWrite((this.addr + i) & 0xFFFF, info[i]);
        this.finish(M.DKE_OK);
        return false;
      }
      default:   // FLUSH: the debugger images are in memory, there is nothing to save
        this.finish(M.DKE_OK);
        return false;
    }
    this.lba = (this.lba + 1) >>> 0;
    this.addr = (this.addr + S) & 0xFFFF;
    if (--this.count === 0) { this.finish(M.DKE_OK); return false; }
    return true;
  }
}

class Cpu16Engine {
  constructor() {
    this.name = "JS engine";
    this.isStub = false;
    this.mem = new Uint8Array(MACHINE.PHYS_SIZE);   // 2 MB of physical memory
    this.r = new Uint16Array(16);
    this.pending = 0;              // IRQ0..IRQ7 requests by edge (cleared on entry)
    this.levels = 0;               // level requests (IRQ1 of the disk controller)
    this.waiting = false;          // the WFI state
    this.steps = 0;
    this.dev = new Cpu16Device();  // console, display, keyboard, timer ($FF20..$FF29)
    this.rtc = new Cpu16Rtc();     // real-time clock ($FF2A..$FF2E)
    this.rtc.setHostTime();
    this.disk = new Cpu16Disk();   // the disk controller ($FF30..$FF3B)
    this.disk.dmaRead = (a) => this.mem[this.pageOff[a >> 13] + (a & 0x1FFF)];
    this.disk.dmaWrite = (a, v) => { this.mem[this.pageOff[a >> 13] + (a & 0x1FFF)] = v; };
    this.disk.sectorDelayUs = 1000; // in the debugger: 1 ms per sector (changed by the Disks panel)
    this.mmuPage = new Uint8Array(MACHINE.PAGE_COUNT);
    this.mmuCtrl = 0;
    this.pageOff = new Int32Array(MACHINE.PAGE_COUNT);   // the frame offset of each page in mem
    this.remap();
    this.pollCounter = 0;          // polling devices once per 256 steps, as in cpu16.cpp
  }
  // The memory manager: page frame offsets by the PAGE registers and the EN bit.
  remap() {
    for (let p = 0; p < MACHINE.PAGE_COUNT; p++)
      this.pageOff[p] = ((this.mmuCtrl & MACHINE.MMU_EN) ? this.mmuPage[p] : p) * MACHINE.PAGE_SIZE;
  }
  physAddr(a) { a &= 0xFFFF; return this.pageOff[a >> 13] + (a & 0x1FFF); }
  syncIrq() { this.levels = this.disk.irq() ? 2 : 0; }

  // ---------------- the contract: state ----------------
  get state() { return this.waiting ? "waiting" : "stopped"; }
  get pendingIrqs() { return this.pending | this.levels; }
  get pendingInput() { return this.dev.keys.length; }
  get timerEnabled() { return this.dev.timerOn; }
  get diskBusy() { return this.disk.busy; }
  // Whether anything can wake the processor in WFI: the timer or a disk command that will raise IRQ1.
  get canWake() { return this.dev.timerOn || this.disk.willIrq(); }
  get usedDisplay() { return this.dev.usedDisplay; }

  // The keyboard: events { character, scancode, modifiers }. feedInput - bytes as characters without a scancode.
  feedKey(ch, scan, mods = 0) { this.dev.pushKey(ch, scan, mods); }
  feedInput(bytes) { for (const b of bytes) this.dev.pushKey(b, 0); }
  // Text (a JS string) -> events: characters are recoded into the machine encoding, the others are skipped.
  feedText(text) {
    for (const ch of text.replace(/\r\n?/g, "\n")) {
      const code = Cpu16Engine.charsetCode(ch.codePointAt(0));
      if (code > 0) this.dev.pushKey(code, 0);
    }
  }
  clearInput() { this.dev.keys = []; }
  static charsetCode(cp) {
    if (cp < 0x80) return cp;
    if (!Cpu16Engine.reverse) {
      Cpu16Engine.reverse = new Map();
      MACHINE.charset.forEach((u, i) => { if (i >= 0x80 || (i > 0 && i < 0x20) || i === 0x7F) Cpu16Engine.reverse.set(u, i); });
    }
    const c = Cpu16Engine.reverse.get(cp);
    return c === undefined ? -1 : c;
  }
  // The screen for drawing: characters, attributes, position, mode, a version number (grows on changes).
  getScreen() {
    const d = this.dev;
    return { chars: d.chars, attrs: d.attrs, col: d.col, row: d.row, ctrl: d.ctrl, version: d.screenVersion };
  }
  // The timer and disk exchange in the debugger: they stand on pause, on resume counting starts anew.
  setClockFrozen(frozen) {
    if (frozen) { this.dev.clockFrozen = true; this.disk.clockFrozen = true; }
    else { this.dev.resumeClock(); this.disk.resumeClock(); }
  }
  // Poll devices now (the host waits for an event in WFI): like c.poll() in cpu16.cpp.
  pollDevices() {
    if (this.dev.pollTimer()) this.pending |= 1;
    this.disk.poll();
    this.syncIrq();
  }
  pollTimerNow() { this.pollDevices(); }

  // ---------------- the contract: disks ----------------
  // Attach an image: bytes (the length is a multiple of 512), name is the file name (the label comes from it).
  attachDisk(n, bytes, name, readOnly = false) {
    if (bytes.length % MACHINE.SECTOR_SIZE) throw new Error(`size ${bytes.length} is not a multiple of 512`);
    this.disk.attach(n, { data: bytes, readOnly: !!readOnly, removable: true, label: cpu16DiskLabel(name), name, modified: false });
    this.syncIrq();
  }
  detachDisk(n) { this.disk.detach(n); this.syncIrq(); }
  setDiskReadOnly(n, ro) { const d = this.disk.disks[n & 7]; if (d) d.readOnly = !!ro; }
  getDisks() {
    return this.disk.disks.map((d, n) => d && { n, name: d.name, sectors: Cpu16Disk.sectors(d), readOnly: d.readOnly,
                                                label: String.fromCodePoint(...[...d.label].map((b) => MACHINE.charset[b] || 0x3F)),
                                                modified: !!d.modified });
  }
  getDiskImage(n) { const d = this.disk.disks[n & 7]; return d ? d.data : null; }
  get diskDelayMs() { return this.disk.sectorDelayUs / 1000; }
  set diskDelayMs(ms) { this.disk.sectorDelayUs = Math.max(0, Math.round(ms * 1000)); }
  getDiskRegs() {
    const k = this.disk;
    return { status: k.status(), error: k.error, disk: k.disk, count: k.count, addr: k.addr, lba: k.lba, ctrl: k.ctrl, drives: k.drives() };
  }

  // ---------------- the contract: the memory manager ----------------
  getMmu() {
    return { enabled: !!(this.mmuCtrl & MACHINE.MMU_EN), pages: Array.from(this.mmuPage),
             phys: Array.from(this.pageOff) };
  }
  setMmuPage(p, frame) { this.mmuPage[p & 7] = frame & 0xFF; this.remap(); }
  setMmuEnabled(on) { this.mmuCtrl = on ? MACHINE.MMU_EN : 0; this.remap(); }

  // ---------------- the contract: the clock ----------------
  // The clock value (seconds from 2025, ordinary notation, a string) and the exchange registers.
  getRtc() {
    const k = this.rtc, s = k.value();
    return { seconds: s, civil: Cpu16Rtc.civil(s), text: Cpu16Rtc.format(s), time: k.time, date: k.date, err: k.err,
             msToNextSecond: Math.ceil((MACHINE.RTC_SECOND_US - (((k.clock() - k.anchor) % MACHINE.RTC_SECOND_US) + MACHINE.RTC_SECOND_US) % MACHINE.RTC_SECOND_US) / 1000) };
  }
  // Set the clock from the debugger: the string "DD.MM.YYYY HH:MM:SS" (24-hour notation). The fraction of a second
  // is reset, the TIME, DATE and ERR registers do not change (this is not a program command). false - not accepted.
  setRtc(text) {
    const s = Cpu16Rtc.parse(text);
    if (s === null) return false;
    this.rtc.setNow(s);
    return true;
  }
  setRtcHostTime() { this.rtc.setHostTime(); }

  // Machine reset: the processor, devices (the screen, keyboard, timer, clock registers and disk controller
  // registers), the memory manager is off, PAGE0..PAGE7 = 0. Memory, attached disks, the clock value
  // and its running are not touched.
  reset() {
    this.r.fill(0);
    this.pending = 0;
    this.levels = 0;
    this.waiting = false;
    this.steps = 0;
    this.pollCounter = 0;
    const frozen = this.dev.clockFrozen;
    this.dev.reset();
    this.dev.clockFrozen = frozen;
    this.rtc.reset();
    this.disk.reset();
    this.mmuPage.fill(0);
    this.mmuCtrl = 0;
    this.remap();
  }
  // The image is by logical addresses (after reset the manager is off: these are physical addresses too).
  loadImage(bytes, addr) {
    for (let i = 0; i < bytes.length; i++) this.mem[this.physAddr(addr + i)] = bytes[i];
    return `Loaded ${bytes.length} bytes at ${Cpu16Engine.hex4(addr)}.`;
  }
  clearMemory() { this.mem.fill(0); }

  getRegs() { return Uint16Array.from(this.r); }
  setReg(n, v) { this.r[n] = v & (n === 14 ? 0xFFFE : n === 15 ? 0x001F : 0xFFFF); }
  // Logical addresses through the memory manager; the device window gives register values without side
  // effects (a keyboard event is not taken), addresses without a device give 0.
  readMem(addr, len) {
    const out = new Uint8Array(len);
    for (let i = 0; i < len; i++) out[i] = this.peek8((addr + i) & 0xFFFF);
    return out;
  }
  // A write from the debugger: memory at a logical address; the device window is not written.
  writeMem(addr, bytes) {
    for (let i = 0; i < bytes.length; i++) {
      const a = (addr + i) & 0xFFFF;
      if (a < MACHINE.IO_BASE) this.mem[this.physAddr(a)] = bytes[i];
    }
  }
  readPhys(addr, len) {
    const out = new Uint8Array(len);
    for (let i = 0; i < len; i++) out[i] = this.mem[(addr + i) % MACHINE.PHYS_SIZE];
    return out;
  }
  writePhys(addr, bytes) { for (let i = 0; i < bytes.length; i++) this.mem[(addr + i) % MACHINE.PHYS_SIZE] = bytes[i]; }
  peek8(a) {
    a &= 0xFFFF;
    if (a < MACHINE.IO_BASE) return this.mem[this.pageOff[a >> 13] + (a & 0x1FFF)];
    if (Cpu16Device.isPort(a)) {
      if (a === MACHINE.PORT_DATA) return this.dev.keys.length ? this.dev.keys[0].ch : 0;
      if (a === MACHINE.PORT_SCAN) return this.dev.keys.length ? this.dev.keys[0].scan : 0;
      return this.dev.read8(a);
    }
    if (a === MACHINE.PORT_MODS) return this.dev.mods;
    if (a === MACHINE.PORT_SCRD) return this.dev.readCell(false) & 0xFF;
    if (a === MACHINE.PORT_SCRD + 1) return this.dev.readCell(false) >> 8;
    if (Cpu16Rtc.isPort(a)) return this.rtc.read8(a);
    if (Cpu16Disk.isPort(a)) return this.disk.read8(a);
    if (a >= MACHINE.MMU_FIRST && a <= MACHINE.MMU_LAST) return a === MACHINE.MMU_CTRL ? this.mmuCtrl : this.mmuPage[a - MACHINE.MMU_PAGE0];
    return 0;
  }
  raiseIrq(n) {
    this.pending |= 1 << (n & 7);
    const ifSet = this.r[15] & ISA.IF;
    return { reason: "irq", message: `IRQ${n} requested. ` + (ifSet ? "It is taken before the next instruction."
                                                                     : "Interrupts are disabled (IF=0); it stays pending" +
                                                                       (this.waiting ? " but wakes the processor from WFI." : ".")) };
  }
  // Text printed in teletype mode: \n and \t as is, \b is the character \b (the log will delete the
  // last character), \r is skipped, the rest are machine encoding characters.
  takeConsoleOutput() {
    const out = this.dev.ttyOut;
    if (!out.length) return "";
    let s = "";
    for (const b of out) {
      if (b === 0x0A || b === 0x09 || b === 0x08) s += String.fromCharCode(b);
      else if (b !== 0x0D) s += String.fromCodePoint(MACHINE.charset[b] || 0x20);
    }
    this.dev.ttyOut = [];
    return s;
  }

  // ---------------- the contract: execution ----------------
  // One instruction or entry into an interrupt. Returns the stop reason.
  step() {
    this.pollCounter = (this.pollCounter + 1) >>> 0;
    if ((this.pollCounter & 255) === 0) this.pollDevices();   // the timer (IRQ0), disks (IRQ1)
    let req = this.pending | this.levels;
    if (this.waiting) {
      // idle: nothing was executed (idle distinguishes this case from a just executed WFI)
      if (!req) return { reason: "waiting", idle: true, timer: this.dev.timerOn, disk: this.disk.willIrq(),
                         message: "Waiting for an interrupt (WFI). Raise an IRQ to continue." };
      this.waiting = false;                     // a request wakes the processor even with IF=0
    }
    if (req && (this.r[15] & ISA.IF)) {
      let n = 0;
      while (!(req & (1 << n))) n++;            // a lower number means higher priority
      this.pending &= ~(1 << n);                // a level request stays while the device holds it
      this.enter(n, this.r[14]);
      this.steps++;
      return { reason: "step", message: `IRQ${n} taken: handler at ${Cpu16Engine.hex4(this.r[14])}.` };
    }
    const msg = this.exec();
    this.steps++;
    // idle only with WFI and no pending requests: otherwise the next step continues work at once
    if (this.waiting && !(this.pending | this.levels))
      return { reason: "waiting", timer: this.dev.timerOn, disk: this.disk.willIrq(), message: "WFI: waiting for an interrupt." };
    return msg ? { reason: "step", message: msg } : { reason: "step" };
  }
  // Up to maxSteps steps; stop BEFORE an instruction at an address from bps (except the very first).
  runChunk(maxSteps, bps) {
    for (let i = 0; i < maxSteps; i++) {
      const s = this.step();
      if (s.reason !== "step") return s;
      if (bps.has(this.r[14])) return { reason: "breakpoint", message: `Breakpoint at ${Cpu16Engine.hex4(this.r[14])}.` };
    }
    return { reason: "limit" };
  }

  // ---------------- the bus ----------------
  // Memory goes through the memory manager; the device window $FF20..$FFFF is selected before translation.
  rd8(a) {
    a &= 0xFFFF;
    if (a < MACHINE.IO_BASE) return this.mem[this.pageOff[a >> 13] + (a & 0x1FFF)];
    if (Cpu16Device.isPort(a)) return this.dev.read8(a);
    if (a === MACHINE.PORT_MODS) return this.dev.mods;
    if (a === MACHINE.PORT_SCRD) return this.dev.readCell(false) & 0xFF;
    if (a === MACHINE.PORT_SCRD + 1) return this.dev.readCell(false) >> 8;
    if (Cpu16Rtc.isPort(a)) return this.rtc.read8(a);
    if (Cpu16Disk.isPort(a)) return this.disk.read8(a);
    if (a >= MACHINE.MMU_FIRST && a <= MACHINE.MMU_LAST) return a === MACHINE.MMU_CTRL ? this.mmuCtrl : this.mmuPage[a - MACHINE.MMU_PAGE0];
    return 0;
  }
  wr8(a, v) {
    a &= 0xFFFF;
    v &= 0xFF;
    if (a < MACHINE.IO_BASE) { this.mem[this.pageOff[a >> 13] + (a & 0x1FFF)] = v; return; }
    if (Cpu16Device.isPort(a)) this.dev.write8(a, v);
    else if (Cpu16Rtc.isPort(a)) this.rtc.write8(a, v);
    else if (Cpu16Disk.isPort(a)) { this.disk.write8(a, v); this.syncIrq(); }
    else if (a >= MACHINE.MMU_FIRST && a <= MACHINE.MMU_LAST) {
      if (a === MACHINE.MMU_CTRL) this.mmuCtrl = v & MACHINE.MMU_EN; else this.mmuPage[a - MACHINE.MMU_PAGE0] = v;
      this.remap();
    }
  }
  // the word is aligned and does not cross a page; the device window - as read16io in cpu16.cpp:
  // a word at $FF20 is one keyboard access, a word at $FF50 (SCRD) is a screen cell with a position shift
  rd16(a) {
    a &= 0xFFFE;
    if (a < MACHINE.IO_BASE) { const p = this.pageOff[a >> 13] + (a & 0x1FFF); return this.mem[p] | (this.mem[p + 1] << 8); }
    if (a === MACHINE.PORT_SCRD) return this.dev.readCell(true);
    return a === MACHINE.PORT_DATA ? this.dev.read16(a) : this.rd8(a) | (this.rd8(a + 1) << 8);
  }
  wr16(a, v) {
    a &= 0xFFFE;
    if (a < MACHINE.IO_BASE) { const p = this.pageOff[a >> 13] + (a & 0x1FFF); this.mem[p] = v & 0xFF; this.mem[p + 1] = (v >> 8) & 0xFF; return; }
    this.wr8(a, v); this.wr8(a + 1, v >> 8);
  }

  // ---------------- execution (the order of sect. 4 of the specification) ----------------
  enter(n, savedIp) {
    const r = this.r;
    r[13] = (r[13] - 2) & 0xFFFF; this.wr16(r[13], savedIp);
    r[13] = (r[13] - 2) & 0xFFFF; this.wr16(r[13], r[15]);
    r[15] &= ~ISA.IF;
    this.setReg(14, this.rd16(ISA.VEC_BASE + 2 * (n & 15)));
  }
  static zs(res) { return (res === 0 ? ISA.ZF : 0) | (res & 0x8000 ? ISA.SF : 0); }
  cond(c) {
    const f = this.r[15];
    const z = !!(f & ISA.ZF), cf = !!(f & ISA.CF), s = !!(f & ISA.SF), o = !!(f & ISA.OF);
    switch (c) {
      case 0: return true;   case 1: return z;          case 2: return !z;
      case 3: return cf;     case 4: return !cf;        case 5: return !cf && !z;
      case 6: return cf || z; case 7: return s;         case 8: return !s;
      case 9: return o;      case 10: return !o;        case 11: return s !== o;
      case 12: return s === o; case 13: return !z && s === o; case 14: return z || s !== o;
      default: return false;
    }
  }
  // Writing the ALU result and flags; with R1=R15 flags are not updated automatically.
  commit(r1, res, f, write) {
    if (write) this.setReg(r1, res);
    if (write && r1 === 15) return;
    this.r[15] = (this.r[15] & ISA.IF) | f;
  }
  // Returns the message text for special events (ERRCMD) or null.
  exec() {
    const r = this.r, O = ISA.OP;
    const start = r[14];
    const w = this.rd16(start);
    r[14] = (start + 2) & 0xFFFF;
    const op = w >> 11, r1 = (w >> 7) & 15, r2 = (w >> 3) & 15, mod = w & 7;

    const why = ISA.reason(w);
    if (why !== 0) {   // an invalid encoding: ERRCMD with no side effects, the instruction address is saved
      this.enter(ISA.VEC_ERRCMD, start);
      return `ERRCMD at ${Cpu16Engine.hex4(start)} (word ${Cpu16Engine.hex4(w)}): ${ISA.reasonText[why]}.`;
    }

    switch (op) {
      case O.MISC: {   // the combined opcode: the operation is in the R2 field (the validity of the subcode is already checked)
        const M = ISA.MISC;
        if (r2 === M.NEG) {
          const a = r[r1], res = (0 - a) & 0xFFFF;
          this.commit(r1, res, Cpu16Engine.zs(res) | (a !== 0 ? ISA.CF : 0) | (a === 0x8000 ? ISA.OF : 0), true);
        } else if (r2 === M.NOT) {
          this.setReg(r1, ~r[r1]);
        } else if (r2 === M.BSX) {
          this.setReg(r1, (r[r1] & 0x80) ? (r[r1] | 0xFF00) : (r[r1] & 0xFF));
        } else if (r2 === M.IRET) {
          const f = this.rd16(r[13]); r[13] = (r[13] + 2) & 0xFFFF;
          const ip = this.rd16(r[13]); r[13] = (r[13] + 2) & 0xFFFF;
          this.setReg(15, f);
          this.setReg(14, ip);
        } else {
          this.waiting = true;   // WFI
        }
        return null;
      }
      case O.JR: {
        if (this.cond(r1)) {
          const off = ((w & 0x7F) ^ 0x40) - 0x40;
          this.setReg(14, r[14] + 2 * off);
        }
        return null;
      }
      default: break;
    }

    const byteOp = ISA.opInfo[op].byteOp;
    const step = byteOp ? 1 : 2;
    let disp = 0;
    if (mod >= 5) { disp = this.rd16(r[14]); r[14] = (r[14] + 2) & 0xFFFF; }
    const a = r[r1];   // the R1 source is fixed before R2 is modified

    let isMem = false, ea = 0, val = 0;
    switch (mod) {
      case 0: val = r[r2]; break;
      case 1: val = r2; break;
      case 2: ea = r[r2]; isMem = true; break;
      case 3:
        if (r2 === 14) { val = this.rd16(r[14]); r[14] = (r[14] + 2) & 0xFFFF; }
        else { ea = r[r2]; this.setReg(r2, ea + step); isMem = true; }
        break;
      case 4: this.setReg(r2, r[r2] - step); ea = r[r2]; isMem = true; break;
      case 5: ea = disp; isMem = true; break;
      case 6: ea = (r[r2] + disp) & 0xFFFF; isMem = true; break;
      case 7: val = (r[r2] + disp) & 0xFFFF; break;
    }
    const load = () => (!isMem ? val : byteOp ? this.rd8(ea) : this.rd16(ea));
    const zs = Cpu16Engine.zs;

    switch (op) {
      case O.LD: this.setReg(r1, load()); return null;
      case O.LDZX: this.setReg(r1, load() & 0xFF); return null;
      case O.LDSX: { const b = load() & 0xFF; this.setReg(r1, b & 0x80 ? b | 0xFF00 : b); return null; }
      case O.ST: this.wr16(ea, a); return null;
      case O.STB: this.wr8(ea, a); return null;
      case O.XCHB: { const old = this.rd8(ea); this.wr8(ea, a); this.setReg(r1, old); return null; }
      case O.ADD: case O.ADC: {
        const b = load();
        const sum = a + b + (op === O.ADC && (r[15] & ISA.CF) ? 1 : 0);
        const res = sum & 0xFFFF;
        let f = zs(res);
        if (sum > 0xFFFF) f |= ISA.CF;
        if (~(a ^ b) & (a ^ res) & 0x8000) f |= ISA.OF;
        this.commit(r1, res, f, true);
        return null;
      }
      case O.SUB: case O.SBC: case O.CMP: {
        const b = load();
        const bw = b + (op === O.SBC && (r[15] & ISA.CF) ? 1 : 0);
        const res = (a - bw) & 0xFFFF;
        let f = zs(res);
        if (a < bw) f |= ISA.CF;   // CF = borrow
        if ((a ^ b) & (a ^ res) & 0x8000) f |= ISA.OF;
        this.commit(r1, res, f, op !== O.CMP);
        return null;
      }
      case O.AND: case O.OR: case O.XOR: case O.TEST: {
        const b = load();
        const res = op === O.OR ? (a | b) : op === O.XOR ? (a ^ b) : (a & b);
        this.commit(r1, res, zs(res), op !== O.TEST);
        return null;
      }
      case O.SHL: case O.SHR: case O.SAR: case O.ROR: {
        const n = load() & 15;
        if (n === 0) return null;   // a shift by 0: nothing changes
        let res, cf;
        if (op === O.SHL) { res = (a << n) & 0xFFFF; cf = (a >> (16 - n)) & 1; }
        else if (op === O.SHR) { res = a >> n; cf = (a >> (n - 1)) & 1; }
        else if (op === O.SAR) { res = ((a << 16) >> 16 >> n) & 0xFFFF; cf = (a >> (n - 1)) & 1; }
        else { res = ((a >> n) | (a << (16 - n))) & 0xFFFF; cf = (res >> 15) & 1; }
        this.commit(r1, res, zs(res) | (cf ? ISA.CF : 0), true);
        return null;
      }
      case O.MUL: case O.MULHU: {   // unsigned 16x16 = 32
        const p = a * load();     // < 2^32: exact in JS numbers
        const hi = Math.floor(p / 65536), res = op === O.MUL ? p & 0xFFFF : hi;
        // MUL: CF = OF = 1 if the high word is not 0; MULHU: CF = OF = 0
        this.commit(r1, res, zs(res) | (op === O.MUL && hi ? ISA.CF | ISA.OF : 0), true);
        return null;
      }
      case O.DIVU: case O.REMU: {   // unsigned 16/16
        const b = load();
        // division by 0: no exception; the quotient is $FFFF, the remainder = the dividend, OF = 1
        const res = b === 0 ? (op === O.DIVU ? 0xFFFF : a) : (op === O.DIVU ? Math.floor(a / b) : a % b);
        this.commit(r1, res, zs(res) | (b === 0 ? ISA.OF : 0), true);
        return null;
      }
      case O.JXX: case O.CALL: case O.TRAP: {
        if (op === O.TRAP) { this.enter(load() & 15, r[14]); return null; }
        const target = mod === 1 ? (r[14] + 2 * (((r2 ^ 8) & 15) - 8)) & 0xFFFF : load();
        if (op === O.CALL) { r[12] = r[14]; this.setReg(14, target); }
        else if (this.cond(r1)) this.setReg(14, target);
        return null;
      }
    }
    return null;
  }

  // ---------------- the disassembler (the syntax of the assembler reference) ----------------
  static hex4(v) { return "$" + (v & 0xFFFF).toString(16).toUpperCase().padStart(4, "0"); }
  // A word for the disassembler and the debugger windows: a logical address, without side effects.
  memWord(a) { a &= 0xFFFE; return this.peek8(a) | (this.peek8(a + 1) << 8); }
  // The length of an instruction word: an invalid word is shown as .word of length 1.
  instrLen(w) { return ISA.valid(w) ? ISA.instrWords(w) : 1; }

  // Parse one instruction at address a. sym(value, kind) -> a name or null, kind:
  //   "target" - a jump target, "memory" - an address in memory, "immediate" - an immediate value.
  decodeAt(a, sym) {
    a &= 0xFFFE;
    const H = Cpu16Engine.hex4;
    const w = this.memWord(a);
    const reg = (n) => ISA.regNames[n];
    const where = (v, kind = "target") => (sym && sym(v & 0xFFFF, kind)) || H(v);
    const row = { addr: a, words: [w], mnemonic: "", operands: "", isCall: false, isData: false, target: null, note: "" };
    const why = ISA.reason(w);
    if (why !== 0) {
      row.mnemonic = ".word"; row.operands = H(w); row.isData = true;
      row.note = ISA.reasonText[why];
      return row;
    }
    const len = ISA.instrWords(w);
    const w2 = this.memWord(a + 2);
    if (len === 2) row.words.push(w2);
    const op = w >> 11, r1 = (w >> 7) & 15, r2 = (w >> 3) & 15, mod = w & 7;
    const info = ISA.opInfo[op], O = ISA.OP, P = ISA.pseudo;

    // pseudo-instructions
    for (const k of ["NOP", "RET", "STI", "CLI", "STC", "CLC", "CMC"]) if (w === P[k]) { row.mnemonic = k; return row; }
    if (w === ISA.encodePush(r1)) { row.mnemonic = "PUSH"; row.operands = reg(r1); return row; }
    if (w === ISA.encodePop(r1)) { row.mnemonic = "POP"; row.operands = reg(r1); return row; }
    if (w === ISA.encodeInc(r1)) { row.mnemonic = "INC"; row.operands = reg(r1); return row; }
    if (w === ISA.encodeDec(r1)) { row.mnemonic = "DEC"; row.operands = reg(r1); return row; }

    // an immediate value: 0..15 as a decimal number (as written in a source), otherwise $XXXX
    const imm = (v) => (v <= 15 ? String(v) : H(v));
    const disp = (d) => (d < 0x8000 ? "+" + H(d) : "-" + H(0x10000 - d));
    // a general R2/MOD operand
    const src = (immAsAddr) => {
      switch (mod) {
        case 0: return reg(r2);
        case 1: return "#" + r2;
        case 2: return `[${reg(r2)}]`;
        case 3: return r2 === 14 ? "#" + (immAsAddr ? where(w2) : (sym && w2 && sym(w2, "immediate")) || imm(w2)) : `[${reg(r2)}++]`;
        case 4: return `[--${reg(r2)}]`;
        case 5: return `[${where(w2, "memory")}]`;
        case 6:
          if (r2 === 14) row.note = `${H(a + 4 + w2)}${sym && sym((a + 4 + w2) & 0xFFFF, "memory") ? " " + sym((a + 4 + w2) & 0xFFFF, "memory") : ""}`;
          return `[${reg(r2)}${disp(w2)}]`;
        case 7:
          if (r2 === 14) row.note = `${H(a + 4 + w2)}${sym && sym((a + 4 + w2) & 0xFFFF) ? " " + sym((a + 4 + w2) & 0xFFFF) : ""}`;
          return `${reg(r2)}${disp(w2)}`;
      }
      return "?";
    };

    switch (info.cls) {
      case "misc":
        row.mnemonic = ISA.miscNames[r2];
        if (r2 <= ISA.MISC.BSX) row.operands = reg(r1);
        return row;
      case "shortbranch": {
        const t = (a + 2 + 2 * (((w & 0x7F) ^ 0x40) - 0x40)) & 0xFFFF;
        row.mnemonic = ISA.condNames[r1]; row.operands = where(t); row.target = t;
        return row;
      }
      case "store":
        row.mnemonic = info.name; row.operands = `${src(false)}, ${reg(r1)}`;
        return row;
      case "branch": {
        row.mnemonic = op === O.CALL ? "CALL" : ISA.condNames[r1];
        row.isCall = op === O.CALL;
        if (mod === 1) {
          const t = (a + 2 + 2 * (((r2 ^ 8) & 15) - 8)) & 0xFFFF;
          row.operands = where(t); row.target = t;
        } else if (mod === 7 && r2 === 14) {
          const t = (a + 4 + w2) & 0xFFFF;
          // an odd target is not written as an address (the assembler will not accept it): show the raw offset
          if (t & 1) row.operands = `IP${disp(w2)}`;
          else { row.operands = where(t); row.target = t; }
        } else if (mod === 3 && r2 === 14) {
          row.operands = "#" + where(w2); row.target = w2 & 0xFFFE;
        } else {
          row.operands = src(true);
        }
        return row;
      }
      case "trap":
        row.mnemonic = "TRAP"; row.operands = src(false);
        return row;
      default: {
        // load, alu, shift, byteload
        row.mnemonic = op === O.LD && mod === 7 ? "LEA" : info.name;
        row.operands = `${reg(r1)}, ${src(false)}`;
        return row;
      }
    }
  }

  // ---------------- the contract: the disassembler ----------------
  disassemble(addr, count, sym) {
    const rows = [];
    let a = addr & 0xFFFE;
    for (let i = 0; i < count; i++) {
      const row = this.decodeAt(a, sym);
      rows.push(row);
      a = (a + 2 * row.words.length) & 0xFFFF;
    }
    return rows;
  }
  // The start of the previous instruction. Instructions are 1 or 2 words long, so going backward cannot be
  // parsed unambiguously: decode forward from a point 16 words earlier and, if the chain arrives
  // exactly at addr, take the previous start; otherwise a simple heuristic by word addr-4.
  prevInstrAddr(addr) {
    addr &= 0xFFFE;
    let a = (addr - 32) & 0xFFFE, prev = -1;
    for (let i = 0; i < 32; i++) {
      if (a === addr) return prev >= 0 ? prev : (addr - 2) & 0xFFFF;
      const d = ((addr - a) & 0xFFFF);
      if (d > 32) break;
      prev = a;
      a = (a + 2 * this.instrLen(this.memWord(a))) & 0xFFFF;
    }
    const w4 = this.memWord((addr - 4) & 0xFFFF);
    return ISA.valid(w4) && ISA.instrWords(w4) === 2 ? (addr - 4) & 0xFFFF : (addr - 2) & 0xFFFF;
  }
}
